<template>
<section><div class="page-head"><div><span class="eyebrow">Video library</span><h1 class="page-title">YouTube</h1><p class="muted">Discover videos and manage your TV sign-in.</p></div><button class="button-secondary" @click="$emit('navigate','addon/youtube')">Add-on details</button></div>
<div class="tabs"><button v-for="tab in ['Trending','My Profile','Sign In','Shorts','Recommended','Subscriptions']" :key="tab" :class="{active:state.youtubeTab===tab}" @click="$emit('action',{action:'youtube-tab',payload:tab})">{{tab}}</button></div>
<div v-if="state.youtubeTab==='Sign In'||state.youtubeTab==='My Profile'" class="card split"><div><span class="eyebrow">Link your TV</span><h2>Sign in to YouTube</h2><p class="muted">Open Google device sign-in on your phone or computer and enter the code shown here.</p><button class="button" @click="$emit('action',{action:'youtube-connect'})">Connect YouTube</button><p><a href="https://www.google.com/device" target="_blank" rel="noopener">Go to google.com/device ↗</a></p></div><div class="callout"><p class="muted">YouTube on TV Code</p><div class="code">{{state.youtubeCode||'ABCD-EFGH-IJKL'}}</div><div v-if="state.youtubeLoading"><div class="progress"><span :style="{width:state.youtubeProgress+'%'}"></span></div><small>{{state.youtubeProgress}}% · Preparing secure device sign-in</small></div><p class="muted">This demo shows the linking flow; sign-in is completed directly with Google.</p></div></div>
<div v-else-if="state.youtubeTab==='Subscriptions'" class="card"><h2>Your subscriptions</h2><p class="muted">Sign in to view your subscriptions on YouTube.</p><button class="button" @click="$emit('action',{action:'youtube-tab',payload:'Sign In'})">Sign in</button></div>
<div v-else class="split"><div class="card"><span class="eyebrow">{{state.youtubeTab}}</span><h2>{{state.youtubeTab==='Shorts'?'Short videos. Big moments.':'A little something to watch.'}}</h2><p class="muted">Browse YouTube to explore {{state.youtubeTab.toLowerCase()}} videos. Video playback is provided by YouTube.</p><form class="row" @submit.prevent="$emit('navigate','https://www.youtube.com/results?search_query='+encodeURIComponent($event.target.query.value))"><input class="input" name="query" placeholder="Search YouTube"><button class="button">Search ↗</button></form></div><div class="card"><iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/videoseries?list=PLrEnWoR732-BHrPp_Pm8_VleD68f9s14-" title="YouTube featured videos" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy"></iframe><p class="muted">Featured videos · YouTube</p></div></div>
<div class="row" style="margin-top:18px"><button class="quiet" @click="$emit('action',{action:'youtube-signout'})">Sign Out</button><a class="muted" href="https://www.youtube.com" target="_blank" rel="noopener">Open YouTube ↗</a></div></section>
</template>
